"""Build and parse tool dispatch payloads for error detection."""

from __future__ import annotations

import ast
import json
from typing import Any, Optional

# Checked in priority order when both keys are present.
_ERROR_RESULT_KEYS: tuple[str, ...] = ("error", "errors")
_RETRYABLE_KEY = "retryable"
INVALID_ARGUMENTS_ERROR_CODE = "invalid_arguments"


def format_error_as_json(message: str) -> str:
    """Serialise a dispatch failure for the LLM and tracker error detection."""
    return json.dumps({"error": message})


def format_retryable_error_as_json(message: str, *, code: str) -> str:
    """Serialise a recoverable dispatch failure for the next LLM iteration."""
    return json.dumps(
        {
            "error": message,
            _RETRYABLE_KEY: True,
            "code": code,
        }
    )


def is_retryable_tool_error(payload: Any) -> bool:
    """Test whether a tool payload explicitly marks an error as retryable."""
    parsed = _parse_tool_payload(payload)
    is_error, _ = _error_from_parsed_payload(parsed)
    return is_error and isinstance(parsed, dict) and parsed.get(_RETRYABLE_KEY) is True


def is_invalid_arguments_error(payload: Any) -> bool:
    """Test whether a payload is the engine's schema-validation reject."""
    parsed = _parse_tool_payload(payload)
    is_error, _ = _error_from_parsed_payload(parsed)
    return (
        is_error
        and isinstance(parsed, dict)
        and parsed.get(_RETRYABLE_KEY) is True
        and parsed.get("code") == INVALID_ARGUMENTS_ERROR_CODE
    )


def _parse_tool_payload_string(payload_text: str) -> Any | None:
    """Parse a non-empty tool payload string as JSON or a Python literal."""
    for parser in (json.loads, ast.literal_eval):
        try:
            return parser(payload_text)
        except (SyntaxError, ValueError):
            continue
    return None


def _parse_tool_payload(payload: Any) -> Any:
    """Parse a tool payload when it is represented as text."""
    if not isinstance(payload, str):
        return payload
    payload_text = payload.strip()
    if not payload_text:
        return None
    return _parse_tool_payload_string(payload_text)


def _format_tool_error_value(value: Any) -> str:
    """Format an ``error`` or ``errors`` field from a parsed tool payload."""
    if isinstance(value, (list, dict)):
        return json.dumps(value, default=str)
    return str(value)


def _error_from_parsed_payload(parsed: Any) -> tuple[bool, Optional[str]]:
    """Return error state from a parsed tool dispatch payload."""
    if not isinstance(parsed, dict):
        return False, None
    for key in _ERROR_RESULT_KEYS:
        value = parsed.get(key)
        if value:
            return True, _format_tool_error_value(value)
    return False, None


def error_from_tool_payload(payload: Any) -> tuple[bool, Optional[str]]:
    """Return ``(is_error, error_message)`` parsed from a dispatch payload."""
    if payload is None:
        return False, None

    parsed = _parse_tool_payload(payload)
    return _error_from_parsed_payload(parsed)
